#ifndef __CC_PHYSICS_RAYCAST_H__
#define __CC_PHYSICS_RAYCAST_H__

#include "base/ccConfig.h"
#if CC_USE_PHYSICS

#include <vector>
#include "chipmunk/chipmunk.h"
#include "math/Vec2.h"

NS_CC_BEGIN

class PhysicsShape;
class PhysicsBody;
class PhysicsWorld;

struct RayCastHit
{
    PhysicsShape* shape;
    PhysicsBody* body;
    Vec2 point;
    Vec2 normal;
    float fraction;
    float distance;
};

struct RayCastInput
{
    Vec2 origin;
    Vec2 direction;
    float maxDistance;
    unsigned int categoryMask;
    unsigned int collisionMask;
    int groupFilter;
};

class PhysicsRayCast
{
public:
    PhysicsRayCast();
    ~PhysicsRayCast();

    bool init(PhysicsWorld* world);

    bool rayCastFirst(const RayCastInput& input, RayCastHit* outHit);
    int rayCastAll(const RayCastInput& input, RayCastHit* outHits, int maxHits);
    bool rayCastAny(const RayCastInput& input);

    bool rayCastClosest(const Vec2& origin, const Vec2& end, RayCastHit* outHit);
    int rayCastMultiple(const Vec2& origin, const Vec2& end, RayCastHit* outHits, int maxHits);

    int fanRayCast(const Vec2& origin, const Vec2& direction, float angle, int numRays,
                   float maxDistance, RayCastHit* outHits, int maxHits);
    int circleRayCast(const Vec2& center, float radius, int numRays,
                      RayCastHit* outHits, int maxHits);

    bool lineOfSight(const Vec2& from, const Vec2& to, unsigned int obstacleMask);
    float distanceToNearestSurface(const Vec2& origin, const Vec2& direction, float maxDist);

    void setDefaultFilter(unsigned int categoryMask, unsigned int collisionMask, int group);
    void setMaxRayCastDistance(float maxDist);

    static float computeReflectionAngle(const Vec2& inDirection, const Vec2& normal);
    static Vec2 computeReflectionDirection(const Vec2& inDirection, const Vec2& normal);
    static Vec2 computeRefractionDirection(const Vec2& inDirection, const Vec2& normal, float ratio);

private:
    PhysicsWorld* _world;
    cpSpace* _space;
    unsigned int _defaultCategoryMask;
    unsigned int _defaultCollisionMask;
    int _defaultGroup;
    float _maxDistance;
    bool _initialized;

    static void rayCastAllCallback(cpShape* shape, cpVect point, cpVect normal,
                                   cpFloat alpha, void* data);
};

NS_CC_END

#endif // CC_USE_PHYSICS
#endif // __CC_PHYSICS_RAYCAST_H__

