  9	#include <cmath>
 10	#include <algorithm>
 11	#include <vector>
 12	#include "base/ccMacros.h"
 13	#include "physics/CCPhysicsShape.h"
 14	#include "physics/CCPhysicsBody.h"
 15	#include "physics/CCPhysicsWorld.h"
 16	#include "physics/CCPhysicsHelper.h"
 17	
 18	NS_CC_BEGIN
 19	
 20	namespace
 21	{
 22	    // A direction whose squared length is below this is treated as having no direction at all.
 23	    const float RAYCAST_DIRECTION_EPSILON_SQ = 1e-12f;
 24	    const float RAYCAST_TWO_PI = 6.28318530717958647692f;
 25	    // Sentinel returned by distanceToNearestSurface when the ray reaches nothing.
 26	    const float RAYCAST_NO_HIT_DISTANCE = -1.0f;
 27	
 28	    // Payload handed to PhysicsRayCast::rayCastAllCallback through cpSpaceSegmentQuery.
 29	    struct RayCastAllContext
 30	    {
 31	        std::vector<RayCastHit>* hits;
 32	        float rayLength;
 33	    };
 34	
 35	    void resetHit(RayCastHit* hit)
 36	    {
 37	        if (hit == nullptr)
 38	        {
 39	            return;
 40	        }
 41	
 42	        hit->shape = nullptr;
 43	        hit->body = nullptr;
 44	        hit->point = Vec2::ZERO;
 45	        hit->normal = Vec2::ZERO;
 46	        hit->fraction = 0.0f;
 47	        hit->distance = 0.0f;
 48	    }
 49	
 50	    bool compareByFraction(const RayCastHit& lhs, const RayCastHit& rhs)
 51	    {
 52	        return lhs.fraction < rhs.fraction;
 53	    }
 54	
 55	    // PhysicsWorld does not expose its cpSpace, so it is read back from the first body that
 56	    // already lives in a space. A world that was still empty when init() ran therefore becomes
 57	    // resolvable as soon as it owns a body, which is why callers re-resolve lazily.
 58	    cpSpace* resolveSpace(PhysicsWorld* world)
 59	    {
 60	        if (world == nullptr)
 61	        {
 62	            return nullptr;
 63	        }
 64	
 65	        const Vector<PhysicsBody*>& bodies = world->getAllBodies();
 66	        for (const auto& body : bodies)
 67	        {
 68	            if (body == nullptr)
 69	            {
 70	                continue;
 71	            }
 72	
 73	            cpBody* cpBodyRef = body->getCPBody();
 74	            if (cpBodyRef == nullptr)
 75	            {
 76	                continue;
 77	            }
 78	
 79	            cpSpace* space = cpBodyGetSpace(cpBodyRef);
 80	            if (space != nullptr)
 81	            {
 82	                return space;
 83	            }
 84	        }
 85	
 86	        return nullptr;
 87	    }
 88	
 89	    cpSpace* activeSpace(PhysicsWorld* world, cpSpace*& cached)
 90	    {
 91	        if (cached == nullptr)
 92	        {
 93	            cached = resolveSpace(world);
 94	        }
 95	
 96	        return cached;
 97	    }
 98	
 99	    cpShapeFilter buildFilter(unsigned int categories, unsigned int mask, int group)
100	    {
101	        // An empty bitmask would reject every shape, so zero is read as "unfiltered".
102	        cpBitmask filterCategories = (categories == 0) ? CP_ALL_CATEGORIES : static_cast<cpBitmask>(categories);
103	        cpBitmask filterMask = (mask == 0) ? CP_ALL_CATEGORIES : static_cast<cpBitmask>(mask);
104	
105	        return cpShapeFilterNew(static_cast<cpGroup>(group), filterCategories, filterMask);
106	    }
107	
108	    // Values left at zero in the input fall back to the filter installed by setDefaultFilter.
109	    cpShapeFilter filterForInput(const RayCastInput& input, unsigned int defaultCategories,
110	                                 unsigned int defaultMask, int defaultGroup)
111	    {
112	        return buildFilter(input.categoryMask != 0 ? input.categoryMask : defaultCategories,
113	                           input.collisionMask != 0 ? input.collisionMask : defaultMask,
114	                           input.groupFilter != 0 ? input.groupFilter : defaultGroup);
115	    }
116	
117	    // Normalises the direction and clamps the requested length to the configured maximum.
118	    bool prepareRay(const Vec2& direction, float requestedLength, float maxLength,
119	                    Vec2* outDirection, float* outLength)
120	    {
121	        if (outDirection == nullptr || outLength == nullptr)
122	        {
123	            return false;
124	        }
125	
126	        *outDirection = Vec2::ZERO;
127	        *outLength = 0.0f;
128	
129	        if (requestedLength <= 0.0f)
130	        {
131	            return false;
132	        }
133	
134	        float directionLengthSq = direction.lengthSquared();
135	        if (directionLengthSq <= RAYCAST_DIRECTION_EPSILON_SQ)
136	        {
137	            return false;
138	        }
139	
140	        *outDirection = direction * (1.0f / std::sqrt(directionLengthSq));
141	        *outLength = (maxLength > 0.0f && requestedLength > maxLength) ? maxLength : requestedLength;
142	
143	        return true;
144	    }
145	
146	    // Single closest hit along origin + direction * length. outHit may be null for existence tests.
147	    bool segmentFirstHit(cpSpace* space, const Vec2& origin, const Vec2& direction, float length,
148	                         const cpShapeFilter& filter, RayCastHit* outHit)
149	    {
150	        resetHit(outHit);
151	
152	        if (space == nullptr || length <= 0.0f)
153	        {
154	            return false;
155	        }
156	
157	        cpSegmentQueryInfo info;
158	        info.shape = nullptr;
159	        info.point = cpvzero;
160	        info.normal = cpvzero;
161	        info.alpha = 0.0;
162	
163	        const Vec2 end = origin + direction * length;
164	        cpShape* cpShapeHit = cpSpaceSegmentQueryFirst(space,
165	                                                       PhysicsHelper::point2cpv(origin),
166	                                                       PhysicsHelper::point2cpv(end),
167	                                                       0.0f,
168	                                                       filter,
169	                                                       &info);
170	        if (cpShapeHit == nullptr)
171	        {
172	            return false;
173	        }
174	
175	        if (outHit != nullptr)
176	        {
177	            PhysicsShape* physicsShape = static_cast<PhysicsShape*>(cpShapeGetUserData(cpShapeHit));
178	            outHit->shape = physicsShape;
179	            outHit->body = (physicsShape != nullptr) ? physicsShape->getBody() : nullptr;
180	            outHit->point = PhysicsHelper::cpv2point(info.point);
181	            outHit->normal = PhysicsHelper::cpv2point(info.normal);
182	            outHit->fraction = PhysicsHelper::cpfloat2float(info.alpha);
183	            outHit->distance = outHit->fraction * length;
184	        }
185	
186	        return true;
187	    }
188	}
189	
190	PhysicsRayCast::PhysicsRayCast()
191	: _world(nullptr)
192	, _space(nullptr)
193	, _defaultCategoryMask(0xFFFFFFFF)
194	, _defaultCollisionMask(0xFFFFFFFF)
195	, _defaultGroup(0)
196	, _maxDistance(10000.0f)
197	, _initialized(false)
198	{
199	}
200	
201	PhysicsRayCast::~PhysicsRayCast()
202	{
203	}
