205	bool PhysicsRayCast::init(PhysicsWorld* world)
206	{
207	    CCASSERT(world != nullptr, "world shouldn't be nullptr");
208	
209	    if (world == nullptr)
210	    {
211	        return false;
212	    }
213	
214	    _world = world;
215	    // A world without bodies has no reachable cpSpace yet; queries resolve it later on demand.
216	    _space = resolveSpace(world);
217	    _initialized = true;
218	
219	    return true;
220	}
221	
222	bool PhysicsRayCast::rayCastFirst(const RayCastInput& input, RayCastHit* outHit)
223	{
224	    resetHit(outHit);
225	
226	    if (!_initialized)
227	    {
228	        return false;
229	    }
230	
231	    Vec2 direction;
232	    float length = 0.0f;
233	    if (!prepareRay(input.direction, input.maxDistance, _maxDistance, &direction, &length))
234	    {
235	        return false;
236	    }
237	
238	    cpSpace* space = activeSpace(_world, _space);
239	    if (space == nullptr)
240	    {
241	        return false;
242	    }
243	
244	    cpShapeFilter filter = filterForInput(input, _defaultCategoryMask, _defaultCollisionMask, _defaultGroup);
245	
246	    return segmentFirstHit(space, input.origin, direction, length, filter, outHit);
247	}
248	
249	int PhysicsRayCast::rayCastAll(const RayCastInput& input, RayCastHit* outHits, int maxHits)
250	{
251	    if (outHits == nullptr || maxHits <= 0 || !_initialized)
252	    {
253	        return 0;
254	    }
255	
256	    Vec2 direction;
257	    float length = 0.0f;
258	    if (!prepareRay(input.direction, input.maxDistance, _maxDistance, &direction, &length))
259	    {
260	        return 0;
261	    }
262	
263	    cpSpace* space = activeSpace(_world, _space);
264	    if (space == nullptr)
265	    {
266	        return 0;
267	    }
268	
269	    std::vector<RayCastHit> hits;
270	    RayCastAllContext context;
271	    context.hits = &hits;
272	    context.rayLength = length;
273	
274	    const Vec2 end = input.origin + direction * length;
275	    cpShapeFilter filter = filterForInput(input, _defaultCategoryMask, _defaultCollisionMask, _defaultGroup);
276	
277	    cpSpaceSegmentQuery(space,
278	                        PhysicsHelper::point2cpv(input.origin),
279	                        PhysicsHelper::point2cpv(end),
280	                        0.0f,
281	                        filter,
282	                        PhysicsRayCast::rayCastAllCallback,
283	                        &context);
284	
285	    // Nearest hit first; a stable sort keeps the collection order of hits sharing a fraction.
286	    std::stable_sort(hits.begin(), hits.end(), compareByFraction);
287	
288	    int count = static_cast<int>(hits.size());
289	    if (count > maxHits)
290	    {
291	        count = maxHits;
292	    }
293	
294	    for (int i = 0; i < count; ++i)
295	    {
296	        outHits[i] = hits[i];
297	    }
298	
299	    return count;
300	}
301	
302	bool PhysicsRayCast::rayCastAny(const RayCastInput& input)
303	{
304	    if (!_initialized)
305	    {
306	        return false;
307	    }
308	
309	    Vec2 direction;
310	    float length = 0.0f;
311	    if (!prepareRay(input.direction, input.maxDistance, _maxDistance, &direction, &length))
312	    {
313	        return false;
314	    }
315	
316	    cpSpace* space = activeSpace(_world, _space);
317	    if (space == nullptr)
318	    {
319	        return false;
320	    }
321	
322	    cpShapeFilter filter = filterForInput(input, _defaultCategoryMask, _defaultCollisionMask, _defaultGroup);
323	
324	    // Existence test only: the closest hit is enough and no result is written back.
325	    return segmentFirstHit(space, input.origin, direction, length, filter, nullptr);
326	}
