328	bool PhysicsRayCast::rayCastClosest(const Vec2& origin, const Vec2& end, RayCastHit* outHit)
329	{
330	    Vec2 delta = end - origin;
331	
332	    RayCastInput input;
333	    input.origin = origin;
334	    input.direction = delta;
335	    input.maxDistance = delta.length();
336	    input.categoryMask = _defaultCategoryMask;
337	    input.collisionMask = _defaultCollisionMask;
338	    input.groupFilter = _defaultGroup;
339	
340	    return rayCastFirst(input, outHit);
341	}
342	
343	int PhysicsRayCast::rayCastMultiple(const Vec2& origin, const Vec2& end, RayCastHit* outHits, int maxHits)
344	{
345	    Vec2 delta = end - origin;
346	
347	    RayCastInput input;
348	    input.origin = origin;
349	    input.direction = delta;
350	    input.maxDistance = delta.length();
351	    input.categoryMask = _defaultCategoryMask;
352	    input.collisionMask = _defaultCollisionMask;
353	    input.groupFilter = _defaultGroup;
354	
355	    return rayCastAll(input, outHits, maxHits);
356	}
