358	int PhysicsRayCast::fanRayCast(const Vec2& origin, const Vec2& direction, float angle, int numRays,
359	                               float maxDistance, RayCastHit* outHits, int maxHits)
360	{
361	    if (outHits == nullptr || maxHits <= 0 || numRays <= 0 || !_initialized)
362	    {
363	        return 0;
364	    }
365	
366	    Vec2 centreDirection;
367	    float length = 0.0f;
368	    if (!prepareRay(direction, maxDistance, _maxDistance, &centreDirection, &length))
369	    {
370	        return 0;
371	    }
372	
373	    cpSpace* space = activeSpace(_world, _space);
374	    if (space == nullptr)
375	    {
376	        return 0;
377	    }
378	
379	    cpShapeFilter filter = buildFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);
380	
381	    // The sweep is symmetric around the centre direction: a single ray fires straight ahead,
382	    // otherwise the rays run from -angle/2 to +angle/2 in equal steps.
383	    float centreAngle = centreDirection.getAngle();
384	    float step = (numRays > 1) ? angle / static_cast<float>(numRays - 1) : 0.0f;
385	    float firstAngle = (numRays > 1) ? centreAngle - angle * 0.5f : centreAngle;
386	
387	    int found = 0;
388	    for (int i = 0; i < numRays && found < maxHits; ++i)
389	    {
390	        Vec2 rayDirection = Vec2::forAngle(firstAngle + step * static_cast<float>(i));
391	
392	        RayCastHit hit = {};
393	        if (segmentFirstHit(space, origin, rayDirection, length, filter, &hit))
394	        {
395	            outHits[found] = hit;
396	            ++found;
397	        }
398	    }
399	
400	    return found;
401	}
402	
403	int PhysicsRayCast::circleRayCast(const Vec2& center, float radius, int numRays,
404	                                  RayCastHit* outHits, int maxHits)
405	{
406	    if (outHits == nullptr || maxHits <= 0 || numRays <= 0 || radius <= 0.0f || !_initialized)
407	    {
408	        return 0;
409	    }
410	
411	    float length = (radius > _maxDistance) ? _maxDistance : radius;
412	
413	    cpSpace* space = activeSpace(_world, _space);
414	    if (space == nullptr)
415	    {
416	        return 0;
417	    }
418	
419	    cpShapeFilter filter = buildFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);
420	
421	    // Rays are spread evenly over the full turn, so the last one stops just short of the first.
422	    float step = RAYCAST_TWO_PI / static_cast<float>(numRays);
423	
424	    int found = 0;
425	    for (int i = 0; i < numRays && found < maxHits; ++i)
426	    {
427	        Vec2 rayDirection = Vec2::forAngle(step * static_cast<float>(i));
428	
429	        RayCastHit hit = {};
430	        if (segmentFirstHit(space, center, rayDirection, length, filter, &hit))
431	        {
432	            outHits[found] = hit;
433	            ++found;
434	        }
435	    }
436	
437	    return found;
438	}
439	
440	bool PhysicsRayCast::lineOfSight(const Vec2& from, const Vec2& to, unsigned int obstacleMask)
441	{
442	    if (!_initialized)
443	    {
444	        return false;
445	    }
446	
447	    cpSpace* space = activeSpace(_world, _space);
448	    if (space == nullptr)
449	    {
450	        // No space to query means there is nothing that could block the segment.
451	        return true;
452	    }
453	
454	    Vec2 delta = to - from;
455	    Vec2 direction;
456	    float length = 0.0f;
457	    if (!prepareRay(delta, delta.length(), _maxDistance, &direction, &length))
458	    {
459	        // Both ends coincide, so the target is trivially visible.
460	        return true;
461	    }
462	
463	    cpShapeFilter filter = buildFilter(_defaultCategoryMask,
464	                                       obstacleMask != 0 ? obstacleMask : _defaultCollisionMask,
465	                                       _defaultGroup);
466	
467	    return !segmentFirstHit(space, from, direction, length, filter, nullptr);
468	}
469	
470	float PhysicsRayCast::distanceToNearestSurface(const Vec2& origin, const Vec2& direction, float maxDist)
471	{
472	    if (!_initialized)
473	    {
474	        return RAYCAST_NO_HIT_DISTANCE;
475	    }
476	
477	    Vec2 rayDirection;
478	    float length = 0.0f;
479	    if (!prepareRay(direction, maxDist, _maxDistance, &rayDirection, &length))
480	    {
481	        return RAYCAST_NO_HIT_DISTANCE;
482	    }
483	
484	    cpSpace* space = activeSpace(_world, _space);
485	    if (space == nullptr)
486	    {
487	        return RAYCAST_NO_HIT_DISTANCE;
488	    }
489	
490	    cpShapeFilter filter = buildFilter(_defaultCategoryMask, _defaultCollisionMask, _defaultGroup);
491	
492	    RayCastHit hit = {};
493	    if (!segmentFirstHit(space, origin, rayDirection, length, filter, &hit))
494	    {
495	        return RAYCAST_NO_HIT_DISTANCE;
496	    }
497	
498	    return hit.distance;
499	}
