501	void PhysicsRayCast::setDefaultFilter(unsigned int categoryMask, unsigned int collisionMask, int group)
502	{
503	    _defaultCategoryMask = categoryMask;
504	    _defaultCollisionMask = collisionMask;
505	    _defaultGroup = group;
506	}
507	
508	void PhysicsRayCast::setMaxRayCastDistance(float maxDist)
509	{
510	    if (maxDist <= 0.0f)
511	    {
512	        CCLOG("PhysicsRayCast WARNING: max raycast distance must be positive, keeping %f", _maxDistance);
513	        return;
514	    }
515	
516	    _maxDistance = maxDist;
517	}
